  "page.createAndManageApiKeysToAuthenticateYourMc": "আপনার MCP সার্ভার বা সরাসরি API কলগুলিকে প্রমাণীকরণ করতে API কীগুলি তৈরি করুন এবং পরিচালনা করুন। প্রতিটি কী তৈরির সময় একবার দেখানো হয়, তাই এটি নিরাপদ কোথাও সংরক্ষণ করুন।",
  "page.connectSophionosToYourAiClientViaMcpCreate": "MCP এর মাধ্যমে আপনার AI ক্লায়েন্টের সাথে SophionOS সংযোগ করুন। একটি API কী তৈরি করুন, তারপর আপনার ক্লায়েন্টে কনফিগারটি পেস্ট করুন।",
