  "legal.privacy.whatYouCanExpect": "আপনি কি আশা করতে পারেন",
  "legal.privacy.tahaAalamASoleProprietorTradingAsSophionosIsTheDesignate": "Taha Aalam, SophionOS হিসাবে একটি একমাত্র মালিক ট্রেডিং, মনোনীত অভিযোগ অফিসার। ডাকবাক্সটি পর্যবেক্ষণ করা হয় এবং ডাক ঠিকানা প্রকাশ করা হয়, তাই একটি অভিযোগ লিখিতভাবে উত্থাপন করা যেতে পারে।",
