  "legal.privacy.everyDataPrincipalHasTheRightToLodgeAGrievanceWithUsAndT": "প্রতিটি Data Principal-এর আমাদের কাছে অভিযোগ করার এবং প্রতিক্রিয়া পাওয়ার অধিকার রয়েছে।",
  "legal.privacy.n9GrievanceRedressal": "9. অভিযোগ প্রতিকার",
  "legal.privacy.weDoNotKnowinglyServeAdvertisingToChildrenAndWeDoNotUseB": "আমরা জেনেশুনে শিশুদের বিজ্ঞাপন পরিবেশন করি না, এবং আমরা আচরণগত বিজ্ঞাপন ব্যবহার করি না।",
  "legal.privacy.ifYouBelieveAChildUnder18HasCreatedAnAccountOrProvidedPe": "আপনি যদি বিশ্বাস করেন যে 18-এর অধীনে একটি শিশু একটি অ্যাকাউন্ট তৈরি করেছে বা ব্যক্তিগত ডেটা প্রদান করেছে, তাহলে অভিযোগকারী কর্মকর্তার সাথে যোগাযোগ করুন। আমরা যাচাইকরণের উপর সেই ডেটা মুছে ফেলব এবং প্রতিবেদনটি যাচাই করার জন্য আমাদের যা প্রয়োজন তার বাইরে প্রশ্নটি তদন্ত করার সময় এটি ধরে রাখব না।",
  "legal.privacy.theServiceIsForPeople18AndOverSoWeDoNotAskForAnAgeDeclar": "পরিষেবাটি 18 এবং তার বেশি লোকদের জন্য, তাই আমরা বয়স ঘোষণার জন্য জিজ্ঞাসা করি না এবং আমরা একটি রেকর্ড করি না। আমরা যাচাইযোগ্য পিতামাতার সম্মতি চাই না, কারণ আমরা শিশুদের ব্যক্তিগত ডেটা প্রক্রিয়া করি না; যদি আমরা জানতে পারি যে আমাদের আছে, আমরা তা মুছে ফেলব।",
  "legal.privacy.theServiceIsNotDirectedAtChildrenAndIsNotIntendedForAnyo": "পরিষেবাটি শিশুদের জন্য নির্দেশিত নয় এবং 18 এর অধীনে কারো জন্য নয়। আমরা জেনেশুনে 18 এর কম বয়সী শিশুদের কাছ থেকে ব্যক্তিগত তথ্য সংগ্রহ করি না।",
  "legal.privacy.n8ChildrenAndUnder18Users": "8. শিশু এবং কম 18 ব্যবহারকারী",
  "legal.privacy.withdrawingConsentToMarketingStopsEveryPromotionalEmailI": "বিপণনের জন্য সম্মতি প্রত্যাহার করা প্রতিটি প্রচারমূলক ইমেল অবিলম্বে বন্ধ করে দেয়, অন্য কোন প্রভাব ছাড়াই। শর্তাবলী বা Privacy Policy-এর সম্মতি প্রত্যাহার করার অর্থ হল পরিষেবাটি আর আইনত আপনার জন্য কাজ করতে পারবে না, তাই এটি আপনার অ্যাকাউন্ট বন্ধ করে দেয়। আপনি নিশ্চিত করার আগে অ্যাপটি আপনাকে এটি বলে এবং নিশ্চিত করতে আপনাকে টাইপ করতে বলে।",
  "legal.privacy.asPerTheBoardsProcess": "বোর্ডের প্রক্রিয়া অনুযায়ী",
  "legal.privacy.youMayComplainToTheDataProtectionBoardAtAnyTimeInAdditio": "আপনি আমাদের সাথে যোগাযোগ করার পরিবর্তে বা পরিবর্তে যে কোনো সময় Data Protection Board-এ অভিযোগ করতে পারেন",
  "legal.privacy.acknowledgedWithin48HoursResolvedWithin15Days": "48 ঘন্টার মধ্যে স্বীকৃত, 15 দিনের মধ্যে সমাধান করা হয়েছে",
