  "legal.privacy.youHaveTheFollowingRightsEachOneHasAnInappControlNotJust": "আপনি নিম্নলিখিত অধিকার আছে. প্রতিটির একটি ইন-অ্যাপ নিয়ন্ত্রণ রয়েছে, শুধুমাত্র একটি নীতি অনুচ্ছেদ নয় এবং প্রত্যেকটি কাউকে ইমেল না করে ব্যবহারযোগ্য।",
  "legal.privacy.n7YourRights": "7. আপনার অধিকার",
  "legal.privacy.weKeepBillingTaxAndAccountingRecordsForAsLongAsTheLawReq": "যতক্ষণ আইনের প্রয়োজন হয় ততক্ষণ আমরা বিলিং, ট্যাক্স এবং অ্যাকাউন্টিং রেকর্ড রাখি। আমরা অন্তত এক বছরের জন্য নিরাপত্তা এবং অ্যাক্সেস লগ রাখি। DPDP Rules, 2025-এর অধীনে ডেটা ফিডুশিয়ারি প্রক্রিয়াকরণের জন্য ভারতের কমপক্ষে এক বছরের প্রয়োজন, এবং একই উইন্ডো সর্বত্র আমাদের ঘটনার তদন্তের প্রয়োজনীয়তা কভার করে।",
  "legal.privacy.twoThingsFollowFromTheBackupWindowStatedPlainlyRatherTha": "ব্যাকআপ উইন্ডো থেকে দুটি জিনিস অনুসরণ করা হয়, লুকানোর পরিবর্তে স্পষ্টভাবে বলা হয়েছে: আপনি যদি আপনার অ্যাকাউন্টটি মুছে ফেলেন, 30 দিন আগে নেওয়া একটি স্ন্যাপশটে এখনও আপনার ডেটা থাকতে পারে যতক্ষণ না সেই স্ন্যাপশটটি ঘূর্ণন শেষ না হয়; এবং আমরা কোনও সম্মতি লগ রাখি না, কারণ পরিষেবাটি ব্যবহার করা হল গ্রহণযোগ্যতা এবং এই নথির সংস্করণটি কার্যকরী যা আপনি সম্মত হয়েছেন।",
  "legal.privacy.noneIsKeptAcceptanceIsTheUseOfTheServiceItselfSection2So": "কোনোটাই রাখা হয় না। গ্রহণযোগ্যতা হল পরিষেবার ব্যবহার (বিভাগ 2), তাই ধরে রাখার জন্য আলাদা কিছু নেই",
