  "legal.privacy.ifAClientIsEverExtendedToANewDataTypeOrANewUseForExample": "যদি কোনও ক্লায়েন্টকে কখনও একটি নতুন ডেটা টাইপ বা একটি নতুন ব্যবহারে প্রসারিত করা হয়, উদাহরণস্বরূপ, আপনার খোলা হয়নি এমন সামগ্রী পড়া, এটি একটি নতুন উদ্দেশ্য। এটি এই তালিকায় নিঃশব্দে যোগ করা হয়নি: এটির জন্য এই নীতির একটি নতুন সংস্করণ প্রয়োজন, নতুন কিছু সংগ্রহ করার আগে প্রকাশিত। যে কোনো সময় এআই অ্যাক্সেস পর্যালোচনা এবং প্রত্যাহার করতে Settings → AI Access দেখুন।",
  "legal.privacy.ifYouCreateAnApiKeyAndConnectClaudeCursorCodexOrAnotherM": "আপনি যদি একটি API কী তৈরি করেন এবং Claude, Cursor, Codex, বা অন্য MCP ক্লায়েন্টকে সংযুক্ত করেন, তাহলে সেই ক্লায়েন্ট SophionOS কে কল করে এবং এর প্রদানকারী যা গ্রহণ করে তা প্রক্রিয়া করে। আপনি এটি সেট আপ করার কারণে এটি ঘটে এবং অনুরোধটি আমাদের ছেড়ে যাওয়ার পরে এটি আমাদের নিয়ন্ত্রণের বাইরে। দেখুন",
