  "legal.privacy.signinAccountRecoverySecurityAlerts": "সাইন ইন, অ্যাকাউন্ট পুনরুদ্ধার, নিরাপত্তা সতর্কতা",
  "legal.privacy.emailAddress2": "ইমেইল ঠিকানা",
  "legal.privacy.n31AccountAndIdentity": "3.1 অ্যাকাউন্ট এবং পরিচয়",
  "legal.privacy.weCollectTheMinimumNeededToRunAPersonalLifemanagementPro": "আমরা একটি ব্যক্তিগত জীবন-ব্যবস্থাপনা পণ্য চালানোর জন্য প্রয়োজনীয় ন্যূনতম সংগ্রহ করি। প্রতিটি সারি একটি স্বতন্ত্র উদ্দেশ্য বলে। আমরা এখানে তালিকাভুক্ত নয় এমন উদ্দেশ্যে আপনার ডেটা পুনরায় ব্যবহার করি না; একটি নতুন উদ্দেশ্য প্রবর্তনের জন্য এই নীতির একটি নতুন সংস্করণ প্রয়োজন, যে কোনো নতুন সংগ্রহের আগে প্রকাশিত।",
  "legal.privacy.n3WhatWeCollectAndWhy": "3. আমরা কি সংগ্রহ করি এবং কেন",
  "legal.privacy.ifADocumentChangesMateriallyWePublishANewVersionWithItsO": "যদি একটি নথি বস্তুগতভাবে পরিবর্তিত হয়, আমরা তার নিজস্ব সংস্করণ নম্বর এবং কার্যকর তারিখ সহ একটি নতুন সংস্করণ প্রকাশ করি এবং এটি কার্যকর হওয়ার আগে আমরা আপনাকে বলি (15 বিভাগ দেখুন)। আমরা একটি পুরানো শর্তাবলীর অধীনে আপনি গ্রহণ করা শর্তাবলীতে একটি নতুন সংস্করণ প্রয়োগ করব না।",
  "legal.privacy.toWithdrawConsentToMarketingUseTheUnsubscribeLinkInAnyMe": "বিপণনের সম্মতি প্রত্যাহার করতে, যেকোনো বার্তায় আনসাবস্ক্রাইব লিঙ্কটি ব্যবহার করুন বা আমাদের কাছে লিখুন; পরিষেবা এবং নিরাপত্তা বিজ্ঞপ্তি বিপণন করা হয় না এবং নির্বিশেষে পাঠানো হয়. শর্তাবলী বা Privacy Policy থেকে সম্মতি প্রত্যাহার করতে, Settings → Privacy & data থেকে আপনার অ্যাকাউন্ট মুছুন। প্রত্যাহার করা ঠিক মঞ্জুর করার মতোই সহজ এবং অবিলম্বে কার্যকর হয়।",
  "legal.privacy.thereIsNoConsentBannerBecauseThereIsNothingToConsentToTh": "কোনও সম্মতি ব্যানার নেই, কারণ এতে সম্মতি দেওয়ার কিছু নেই: উপরের নথিগুলি হল সেই শর্তাবলী যার ভিত্তিতে পরিষেবাটি দেওয়া হয় এবং পরিষেবাটি ব্যবহার করা হল গ্রহণযোগ্যতা। আমরা কোন সম্মতি লগ, কোন সম্মতি খাতা, এবং কোন প্রতি-সংস্করণ সম্মতি রেকর্ড রাখি না, তাই দেখার বা প্রত্যাহার করার সিদ্ধান্তের কোন রেকর্ড নেই। কার্যকর প্রতিটি নথির সংস্করণটি সেই নথির শীর্ষে সংস্করণ লাইন।",
  "legal.privacy.twoOfTheThreeAreRequiredBecauseTheServiceCannotFunctionW": "তিনটির মধ্যে দুটি প্রয়োজন কারণ তাদের ছাড়া পরিষেবাটি কাজ করতে পারে না। তৃতীয়টি ঐচ্ছিক এবং কখনই প্রি-টিক করা হয় না।",
  "legal.privacy.promotionalEmailOnly": "শুধুমাত্র প্রচারমূলক ইমেল",
