  "legal.privacy.weDoNotAskForBlanketConsentEachDocumentIsASeparateConsen": "আমরা কম্বল সম্মতি চাই না. প্রতিটি নথি একটি পৃথক সম্মতি আইটেম, এবং আপনি স্বাধীনভাবে তাদের সম্মতি দিতে পারেন:",
