  "legal.terms.billingSurfacesAppearInSettingsBillingOnlyWhenBillingIsE": "বিলিং সারফেসগুলি Settings → Billing-তে প্রদর্শিত হয় যখন আপনার স্থাপনার জন্য বিলিং সক্ষম করা হয়।",
  "legal.terms.mcpAndApiRoutesThatRequireAPaidPlanReturn403ForFreeKeys": "MCP এবং API রুটগুলির জন্য একটি অর্থপ্রদত্ত প্ল্যানের প্রয়োজন ফ্রি কীগুলির জন্য 403 ফেরত দেয়।",
  "legal.terms.theAuthoritativeNumbersArePublishedInTheAppUnderSettings": "Settings → AI Access এর অধীনে অ্যাপটিতে প্রামাণিক নম্বরগুলি প্রকাশিত হয়েছে। একটি সীমা অতিক্রম করা HTTP 429 প্রদান করে; ফিরে যান এবং পুনরায় চেষ্টা করুন।",
  "legal.terms.rateLimitsArePerMinuteAndEnforcedPerPlan": "রেট সীমা প্রতি মিনিটে এবং প্রতি প্ল্যান প্রয়োগ করা হয়।",
  "legal.terms.governedCompanyContextAndCompanyBrainOrganizationWorkspa": "নিয়ন্ত্রিত কোম্পানির প্রসঙ্গ এবং কোম্পানির মস্তিষ্ক: প্রতিষ্ঠানের কর্মক্ষেত্র এবং ভূমিকা, AI অ্যাক্সেস নীতি এবং অডিট লগ, অনুমতি-সচেতন অনুসন্ধান, SSO এবং SCIM, SLA এবং বাস্তবায়ন সমর্থন, এবং ডেটা রেসিডেন্সি বিকল্পগুলি। একটি স্বাক্ষরিত আদেশ বা চুক্তির দ্বারা পরিচালিত যেখানে একটি বিদ্যমান।",
