  "legal.terms.unlimitedEntitiesRestApiAndMcpAccessWithPerkeyExpiryLabe": "সীমাহীন সত্তা, প্রতি-কী মেয়াদ শেষ হওয়ার সাথে REST API এবং MCP অ্যাক্সেস, লেবেল, স্কোপ, এবং কার্যকলাপের ইতিহাস, জ্ঞান অনুসন্ধান এবং 30-দিনের কার্যকলাপ ধারণ।",
