  "legal.terms.pro": "প্রো",
  "legal.terms.theManagedPersonalWorkspaceWithA100entityCapAreasGoalsPr": "100- সত্তা ক্যাপ সহ পরিচালিত ব্যক্তিগত কর্মক্ষেত্র (ক্ষেত্র, লক্ষ্য, প্রকল্প, কাজ, নোট, সম্পদ, পরিচিতি, যোগাযোগের লগ একত্রিত), 7-দিনের কার্যকলাপ ধরে রাখা এবং ওয়েব অ্যাপের মাধ্যমে ব্যবহার। REST API এবং MCP অ্যাক্সেস অন্তর্ভুক্ত নয় এবং একটি অর্থপ্রদানের পরিকল্পনা প্রয়োজন।",
