  "legal.terms.plan": "পরিকল্পনা",
  "legal.terms.theServiceIsOfferedOnThePlansBelowPricesAreInUsDollarsAn": "পরিষেবাটি নীচের পরিকল্পনাগুলিতে দেওয়া হয়। দাম মার্কিন ডলার এবং পরিবর্তন হতে পারে; আপনি ইতিমধ্যেই অর্থ প্রদান করেছেন এমন একটি সময়ের জন্য কোনো পরিবর্তন কখনোই প্রযোজ্য হয় না। সীমাগুলি প্রযুক্তিগতভাবে প্রয়োগ করা হয়, শুধুমাত্র বর্ণনা করা হয় না: একটি ক্যাপ বা হার সীমা অতিক্রম করে এমন একটি অ্যাকাউন্ট একটি ত্রুটি পায়, অতিরিক্ত নয়।",
  "legal.terms.n3PlansTiersAndTechnicalLimits": "3. পরিকল্পনা, স্তর, এবং প্রযুক্তিগত সীমা",
  "legal.terms.weMaySuspendOrTerminateAnAccountThatBreachesTheseTermsTh": "আমরা এই শর্তাবলী লঙ্ঘন করে এমন একটি অ্যাকাউন্ট স্থগিত বা বন্ধ করতে পারি, যেটি আমাদের আইন দ্বারা স্থগিত করতে হবে, বা আমরা যুক্তিসঙ্গতভাবে বিশ্বাস করি যে ক্ষতির জন্য ব্যবহার করা হচ্ছে। যেখানে আইন অনুমতি দেয়, আমরা আপনাকে কেন বলব এবং আপনাকে প্রথমে সমস্যাটি সমাধান করার সুযোগ দেব।",
  "legal.terms.keepOnePersonToOneAccountAndDoNotShareAnAccountBetweenMu": "এক ব্যক্তিকে একটি অ্যাকাউন্টে রাখুন এবং একাধিক ব্যক্তির মধ্যে একটি অ্যাকাউন্ট শেয়ার করবেন না। আপনি আপনার সেশন এবং API কীগুলির অধীনে কার্যকলাপের জন্য দায়ী যতক্ষণ না আপনি সেগুলি প্রত্যাহার করেন বা সাইন আউট করেন।",
  "legal.terms.allActivityThatHappensUnderYourAccountIncludingActivityB": "আপনার অ্যাকাউন্টের অধীনে ঘটে যাওয়া সমস্ত কার্যকলাপ, যার মধ্যে আপনি যে কাউকে অ্যাক্সেস দেন তার কার্যকলাপ সহ।",
  "legal.terms.keepingYourCredentialsConfidentialAndNotifyingUsAtOnceIf": "আপনার শংসাপত্রগুলি গোপন রাখা এবং আপনি যদি বিশ্বাস করেন যে একটি অ্যাকাউন্টের সাথে আপোস করা হয়েছে তাহলে আমাদেরকে অবিলম্বে অবহিত করা;",
