  "legal.terms.weMayModifySuspendOrDiscontinueFeaturesWhereAChangeMater": "আমরা বৈশিষ্ট্যগুলি সংশোধন, স্থগিত বা বন্ধ করতে পারি। যেখানে একটি পরিবর্তন বস্তুগতভাবে আপনার নির্ভরশীল কার্যকারিতা হ্রাস করে, আমরা এটি কার্যকর হওয়ার আগে পণ্যের মধ্যে যুক্তিসঙ্গত নোটিশ দেব।",
