  "legal.security.treatAnApiKeyAsYourFullIdentityOnTheApiSurfaceItReachesG": "একটি এপিআই কীকে এপিআই পৃষ্ঠে আপনার সম্পূর্ণ পরিচয় হিসাবে বিবেচনা করুন যা এটি পৌঁছায়। কীগুলিকে সংক্ষিপ্ত মেয়াদের দিন দিন, যেখানে সম্ভব সেখানে শুধুমাত্র পঠনযোগ্য ব্যবহার করুন এবং আপনি আর ব্যবহার করবেন না এমন কীগুলি প্রত্যাহার করুন।",
  "legal.security.useAUniquePasswordOnTheIdentityProviderAndTurnOnMultifac": "পরিচয় প্রদানকারীতে একটি অনন্য পাসওয়ার্ড ব্যবহার করুন এবং সেখানে মাল্টি-ফ্যাক্টর প্রমাণীকরণ চালু করুন।",
  "legal.security.yourPart": "আপনার অংশ",
  "legal.security.sophionosIsSelfhostedWhoeverOperatesAnInstanceIsResponsi": "SophionOS স্ব-হোস্টেড: যে কেউ একটি দৃষ্টান্ত পরিচালনা করে সে এটি সুরক্ষিত করার জন্য এবং তাদের জন্য প্রযোজ্য যে কোনও লঙ্ঘন-বিজ্ঞপ্তি কর্তব্য পূরণের জন্য দায়ী।",
