  "legal.security.accessAndSecurityLoggingRetainedForAtLeastOneYearWithRev": "ঘটনার প্রতিক্রিয়া এবং সন্দেহজনক কার্যকলাপের সময় পর্যালোচনা সহ অন্তত এক বছরের জন্য অ্যাক্সেস এবং নিরাপত্তা লগিং বজায় রাখা হয়।",
