  "legal.security.tlsInTransitProvidersideEncryptionAtRestAes256gcmFieldle": "ট্রানজিটে TLS, বিশ্রামে প্রদানকারী-সাইড এনক্রিপশন, ব্যক্তিগত বিষয়বস্তুর AES-256-GCM ফিল্ড-লেভেল এনক্রিপশন, হ্যাশ করা API কী, এবং প্রতি-ব্যবহারকারী সারি বিচ্ছিন্নতা।",
  "legal.security.encryptionObfuscationMaskingOrVirtualTokensForPersonalDa": "ব্যক্তিগত ডেটার জন্য এনক্রিপশন, অস্পষ্টতা, মাস্কিং বা ভার্চুয়াল টোকেন",
