  "legal.security.whereTheDpdpRules2025ApplyRule6RequiresADataFiduciaryToT": "যেখানে DPDP Rules, 2025 প্রযোজ্য, নিয়ম 6-এর জন্য একটি Data Fiduciary প্রয়োজন, ন্যূনতম, নিম্নলিখিত ব্যবস্থাগুলি গ্রহণ করা। যেখানে তারা আপনার জন্য প্রযোজ্য, আমরা তাদের সাথে নিম্নরূপ দেখা করি:",
  "legal.security.indiaMinimumSafeguardsUnderRule6DpdpRules2025": "ভারত: নিয়ম 6, DPDP Rules 2025 এর অধীনে ন্যূনতম সুরক্ষা",
  "legal.security.productionCredentialsAreHeldByTheFounderoperatorAndUsedF": ": প্রোডাকশন শংসাপত্রগুলি প্রতিষ্ঠাতা/অপারেটর দ্বারা ধারণ করা হয় এবং ঘটনা প্রতিক্রিয়া, আপনার শুরু করা একটি সমর্থন বৃদ্ধি বা আইনি প্রক্রিয়ার জন্য ব্যবহৃত হয়। সমর্থন কখনই কাঁচা API কী, পাসওয়ার্ড, সেশন টোকেন বা আপনার নোটগুলির সম্পূর্ণ ডাম্পের জন্য জিজ্ঞাসা করবে না।",
  "legal.security.operatorAccess": "অপারেটর অ্যাক্সেস",
  "legal.security.cloudTakesProviderbackedBackupsTheyAreNotZeroknowledgeTh": ": ক্লাউড প্রোভাইডার-ব্যাকড ব্যাকআপ নেয়। এগুলি শূন্য-জ্ঞান নয়: অপারেটর এনক্রিপশন কী ধারণ করে, তাই ব্যাকআপের বিষয়বস্তু আমাদের দ্বারা পাঠযোগ্য।",
  "legal.security.backupsRecovery": "ব্যাকআপ এবং পুনরুদ্ধার",
  "legal.security.securityAndAccessLogsRetainedForAtLeastOneYearSoThatUnau": ": নিরাপত্তা এবং অ্যাক্সেস লগ, অন্তত এক বছরের জন্য ধরে রাখা, যাতে অননুমোদিত অ্যাক্সেস সনাক্ত করা যায়, তদন্ত করা যায় এবং প্রতিকার করা যায়।",
  "legal.security.loggingAndVisibility": "লগিং এবং দৃশ্যমানতা",
  "legal.security.aGlobalAiaccessSwitchASeparateWriteaccessSwitchPerkeyWri": ": একটি গ্লোবাল এআই-অ্যাক্সেস সুইচ, একটি পৃথক লিখন-অ্যাক্সেস সুইচ, প্রতি-কী লেখার মোড, এবং কার্যকলাপ মেটাডেটা যা আপনি পর্যালোচনা করতে পারেন। একটি কী প্রত্যাহার করা হলে পরবর্তী অনুরোধগুলি অবিলম্বে প্রত্যাখ্যান করে।",
  "legal.security.aiControls": "এআই নিয়ন্ত্রণ করে",
  "legal.security.storedOnlyAsCryptographicHashesShownOnceAtCreationRevoca": ": শুধুমাত্র ক্রিপ্টোগ্রাফিক হ্যাশ হিসাবে সংরক্ষিত, তৈরির সময় একবার দেখানো, প্রত্যাহারযোগ্য, ঐচ্ছিক মেয়াদ সহ, প্রতি-কী লেবেল এবং স্কোপ, এবং MCP-এর জন্য শুধুমাত্র পঠনযোগ্য ডিফল্ট ভঙ্গি।",
  "legal.security.providersideEncryptionOnTheirStorageLayerPlusApplication": ": তাদের স্টোরেজ স্তরে প্রদানকারী-সাইড এনক্রিপশন, প্লাস আপনার ব্যক্তিগত সামগ্রীর অ্যাপ্লিকেশন-স্তরের ক্ষেত্র-স্তরের এনক্রিপশন। SophionOS Cloud-এ, নোট বডি, যোগাযোগের বিশদ বিবরণ এবং আপনার এলাকা, লক্ষ্য, প্রকল্প, কাজ এবং সংস্থানগুলির বিবরণ এবং সংরক্ষিত লিঙ্কগুলি ডাটাবেসে লেখার আগে AES-256-GCM দিয়ে এনক্রিপ্ট করা হয়। এটি প্রতিটি ক্লাউড অ্যাকাউন্টের জন্য সর্বদা চালু থাকে এবং কী কখনই ব্রাউজারে পৌঁছায় না। এটি এন্ড-টু-এন্ড এনক্রিপশন নয়; সার্ভার কী ধারণ করে।",
  "legal.security.encryptionAtRest": "বিশ্রামে এনক্রিপশন",
  "legal.security.allTrafficIsServedOverTlsAndAPerrequestNoncebasedContent": ": সমস্ত ট্র্যাফিক টিএলএস-এর মাধ্যমে পরিবেশন করা হয় এবং প্রতি-অনুরোধ-ভিত্তিক বিষয়বস্তু নিরাপত্তা নীতি অ্যাপটি কোন স্ক্রিপ্টগুলি চালাবে তা সীমাবদ্ধ করে।",
