  "legal.security.free": "বিনামূল্যে",
  "legal.security.postgresRowlevelSecurityEnforcesThatASessionSeesOnlyItsO": ": Postgres সারি-স্তরের নিরাপত্তা প্রয়োগ করে যে একটি সেশন শুধুমাত্র তার নিজস্ব ব্যবহারকারীর সারি দেখতে পায়। API-কী পাথ প্রমাণীকৃত ব্যবহারকারী আইডি দ্বারা প্রতিটি প্রশ্ন ফিল্টার করে। পরিকল্পনা এবং এনটাইটেলমেন্ট চেক সার্ভার-সাইড এবং ব্যর্থ বন্ধ: একটি অনুপস্থিত বা নিষ্ক্রিয় সাবস্ক্রিপশন সমাধান করে",
  "legal.security.peruserIsolation": "প্রতি ব্যবহারকারী বিচ্ছিন্নতা",
  "legal.security.authenticationAndSessionsAreHandledByClerkIncludingSessi": ": সাইন-আউটে সেশন প্রত্যাহার সহ Clerk দ্বারা প্রমাণীকরণ এবং সেশন পরিচালনা করা হয়। আমরা কখনই আপনার পাসওয়ার্ড সংরক্ষণ করি না।",
  "legal.security.accountSecurity": "অ্যাকাউন্ট নিরাপত্তা",
  "legal.security.whatWeDo": "আমরা কি করি",
  "legal.security.replacesThePreviousSecurityPageAddsTheMinimumSafeguardsR": "আগের নিরাপত্তা পৃষ্ঠাটি প্রতিস্থাপন করে। DPDP Rules, 2025-এর নিয়ম 6 দ্বারা প্রয়োজনীয় ন্যূনতম সুরক্ষা যোগ করে এবং SophionOS Cloud কী প্রদান করে এবং একটি স্ব-হোস্টেড স্থাপনা কী করে না তার মধ্যে একটি স্পষ্ট বিচ্ছেদ।",
  "legal.security.howSophionosProtectsYourData": "কিভাবে SophionOS আপনার ডেটা রক্ষা করে।",
  "legal.subprocessors.weAddAVendorOnlyWhenAFeatureNeedsItAndWeUpdateThisPageAt": "আমরা একটি বিক্রেতা যোগ করি শুধুমাত্র যখন একটি বৈশিষ্ট্যের প্রয়োজন হয়, এবং আমরা একই সময়ে এই পৃষ্ঠাটি আপডেট করি। যদি কোনো পরিবর্তন বস্তুগতভাবে আপনার ব্যক্তিগত ডেটা প্রক্রিয়াকরণের পদ্ধতিকে প্রভাবিত করে, তাহলে এটি কার্যকর হওয়ার আগে আমরা আপনাকে ইমেলের মাধ্যমে জানাই, এবং আপনি প্রথমে আপনার অ্যাকাউন্টকে আপত্তি বা মুছে ফেলতে পারেন। পরিবর্তন সম্পর্কে অবহিত হতে, বা একটি আপত্তি উত্থাপন করতে, লিখুন",
